import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    url = API_URL + user + '/repos'
    headers = {'Accept': 'application/vnd.github+json'}
    try:
        response = requests.get(url, headers=headers,verify=False)
        response.raise_for_status()
        repos = response.json()
    except requests.exceptions.HTTPError as e:
        if response.status_code == 404:
            raise ValueError(f"User '{user}' not found.") from e
        else:
            raise ConnectionError(f"Failed to retrieve repositories: {e}") from e
    except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
        raise ConnectionError(f"Failed to retrieve repositories: {e}") from e
    repo_data = [(repo['name'], repo['created_at']) for repo in repos]
    sorted_repos = sorted(repo_data, key=lambda x: x[1])
    return [repo[0] for repo in sorted_repos]

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except Exception as e:
        raise ValueError(f"Invalid IP range provided: {e}") from e

    active_ips = []
    for ip in network.hosts():
        ip_str = str(ip)
        try:
            response = requests.get(f"http://{ip_str}", timeout=timeout,verify=False)
            if response.status_code == 200:
                active_ips.append(ip_str)
        except Exception:
            continue
    return active_ips

