    except ValueError as e:
        raise ValueError(f"Invalid JSON response from {endpoint}: {e}")

import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not isinstance(url, str):
        raise Exception("Invalid URL provided.")
    if not parameters or not isinstance(parameters, dict):
        raise Exception("Invalid parameters provided.")
    try:
        response = requests.get(url, headers=HEADERS, params=parameters)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to access URL: {e}")
    try:
        data = response.json()
    except json.JSONDecodeError:
        raise Exception("Invalid JSON data received.")
    if not data:
        raise Exception("Empty data received from API.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")
    if df.empty:
        raise Exception("DataFrame is empty.")
    numerical_df = df.select_dtypes(include=['number'])
    if numerical_df.empty:
        raise Exception("No numerical data for correlation.")
    corr = numerical_df.corr()
    fig, ax = plt.subplots()
    sns.heatmap(corr, annot=True, ax=ax)
    return df, ax

