import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(URL + username, verify=False)
    response.raise_for_status()
    data = response.json()
    normalized = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized[key] = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
        else:
            normalized[key] = value
    return normalized

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)
    class DataEndpoint(Resource):
        def get(self):
            resp = requests.get(api_url, verify=False)
            resp.raise_for_status()
            return resp.json()
    api.add_resource(DataEndpoint, '/')
    return app
